<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\{Cart,CartItem,Product}; use Illuminate\Http\Request;
class CartController extends Controller { private function cart($uid){return Cart::firstOrCreate(['user_id'=>$uid]);} public function show(Request $r){return $this->cart($r->user()->id)->load('items.product');} public function add(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id','quantity'=>'required|integer|min:1']);$p=Product::findOrFail($d['product_id']);$cart=$this->cart($r->user()->id);$item=$cart->items()->firstOrNew(['product_id'=>$p->id]);$qty=($item->quantity??0)+$d['quantity'];abort_if($qty>$p->stock,422,'موجودی کافی نیست.');abort_if($qty<$p->minimum_order_quantity,422,'حداقل تعداد سفارش رعایت نشده است.');$item->quantity=$qty;$item->unit_price=$p->final_price;$item->save();return $this->show($r);} public function update(Request $r,CartItem $item){abort_unless($item->cart->user_id===$r->user()->id,403);$d=$r->validate(['quantity'=>'required|integer|min:1']);$p=$item->product;abort_if($d['quantity']>$p->stock,422,'موجودی کافی نیست.');abort_if($d['quantity']<$p->minimum_order_quantity,422,'حداقل تعداد سفارش رعایت نشده است.');$item->update($d);return $this->show($r);} public function remove(Request $r,CartItem $item){abort_unless($item->cart->user_id===$r->user()->id,403);$item->delete();return $this->show($r);} }
